export function InfiniteScroll({
  heading = "{{heading}}",
  accent = "{{accent}}",
  state = "{{state}}",
  postCount = {{postCount}},
  showAvatar = {{showAvatar}},
}) {
  const sentinelText = { idle: "Scroll for more posts.", loading: "Loading more posts…", end: `You're all caught up — ${postCount} posts loaded.` }[state];
  const posts = [["NO", "Nina Osei", "Shipped the new checkout flow today."], ["TN", "Tomas Novak", "Design review moved to Thursday."]];
  return (
    <section aria-label={heading} style={{ fontFamily: "system-ui, sans-serif", fontSize: 13.5, color: "#241430", background: "#FAF7F2", maxWidth: 320, width: 320, padding: 16, borderRadius: 12, boxSizing: "border-box" }}>
      <h3 style={{ margin: "0 0 10px", fontSize: 15, fontWeight: 700 }}>{heading}</h3>
      <ul style={{ listStyle: "none", margin: 0, padding: 0 }}>
        {posts.map(([initials, author, text], i) => (
          <li key={author} style={{ display: "flex", gap: 8, padding: 10, background: "#fff", borderRadius: 8, marginBottom: i === posts.length - 1 ? 0 : 8 }}>
            {showAvatar && <span aria-hidden="true" style={{ width: 26, height: 26, borderRadius: "50%", background: accent, flexShrink: 0, display: "grid", placeItems: "center", fontSize: 10, fontWeight: 700 }}>{initials}</span>}
            <div><p style={{ margin: 0, fontWeight: 700, fontSize: 12.5 }}>{author}</p><p style={{ margin: "2px 0 0", color: "#241430b3" }}>{text}</p></div>
          </li>
        ))}
      </ul>
      <p role="status" style={{ margin: "10px 0 0", fontSize: 12, color: "#241430a0", textAlign: "center" }}>{sentinelText}</p>
    </section>
  );
}
